// Do not edit this file as it will be overwritten if HAMR codegen is rerun
@msig trait ResultComposition_supervisor_process_result_composition_TestApi {

  def BeforeEntrypoint(): Unit = {
    Art.initTest(Arch.DockingAccessSupervisorSystem_Instance_supervisor_process_result_composition)
  }

  def AfterEntrypoint(): Unit = {
    Art.finalizeTest(Arch.DockingAccessSupervisorSystem_Instance_supervisor_process_result_composition)
  }

  def testCompute(): Unit = {
    Art.manuallyClearOutput()
    Art.testCompute(Arch.DockingAccessSupervisorSystem_Instance_supervisor_process_result_composition)
  }

  def testInitialise(): Unit = {
    Art.manuallyClearOutput()
    Art.testInitialise(Arch.DockingAccessSupervisorSystem_Instance_supervisor_process_result_composition)
  }

  /** helper function to set the values of all input ports.
   * @param docking_decision payload for data port docking_decision
   * @param request_disposition payload for data port request_disposition
   */
  def put_concrete_inputs(docking_decision : Docking_Access_Supervisor.DockingDecisionFrame,
                          request_disposition : Docking_Access_Supervisor.RequestDisposition.Type): Unit = {
    put_docking_decision(docking_decision)
    put_request_disposition(request_disposition)
  }


  /** helper function to check ResultComposition_supervisor_process_result_composition's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param docking_access_result method that will be called with the value of the outgoing data
   *        port 'docking_access_result'.
   */
  def check_concrete_output(docking_access_result: Docking_Access_Supervisor.DockingAccessResult => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val docking_access_resultValue: Docking_Access_Supervisor.DockingAccessResult = get_docking_access_result().get
    if(!docking_access_result(docking_access_resultValue)) {
      testFailures = testFailures :+ st"'docking_access_result' did not match expected: value of the outgoing data port is ${docking_access_resultValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


  // setter for in DataPort
  def put_docking_decision(value : Docking_Access_Supervisor.DockingDecisionFrame): Unit = {
    Art.insertInInfrastructurePort(Arch.DockingAccessSupervisorSystem_Instance_supervisor_process_result_composition.operational_api.docking_decision_Id, Docking_Access_Supervisor.DockingDecisionFrame_Payload(value))
  }

  // setter for in DataPort
  def put_request_disposition(value : Docking_Access_Supervisor.RequestDisposition.Type): Unit = {
    Art.insertInInfrastructurePort(Arch.DockingAccessSupervisorSystem_Instance_supervisor_process_result_composition.operational_api.request_disposition_Id, Docking_Access_Supervisor.RequestDisposition_Payload(value))
  }

  // getter for out DataPort
  def get_docking_access_result(): Option[Docking_Access_Supervisor.DockingAccessResult] = {
    val value: Option[Docking_Access_Supervisor.DockingAccessResult] = get_docking_access_result_payload() match {
      case Some(Docking_Access_Supervisor.DockingAccessResult_Payload(v)) => Some(v)
      case Some(v) => halt(s"Unexpected payload on port docking_access_result.  Expecting 'Docking_Access_Supervisor.DockingAccessResult_Payload' but received ${v}")
      case _ => None[Docking_Access_Supervisor.DockingAccessResult]()
    }
    return value
  }

  // payload getter for out DataPort
  def get_docking_access_result_payload(): Option[Docking_Access_Supervisor.DockingAccessResult_Payload] = {
    return Art.observeOutInfrastructurePort(Arch.DockingAccessSupervisorSystem_Instance_supervisor_process_result_composition.initialization_api.docking_access_result_Id).asInstanceOf[Option[Docking_Access_Supervisor.DockingAccessResult_Payload]]
  }

}
